<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import type { WorkspaceFile } from '../../data/workspace'
import { useWorkspace } from '../../state/workspace'
import { useSimulator } from '../../state/simulator'
import { clone, formatBytes, formatDate, matches, usePagination } from './lib/domain'
import WorkspacePager from './WorkspacePager.vue'
import ConfirmDialog from './ConfirmDialog.vue'
import BaseModal from '../common/BaseModal.vue'
import UiIcon from '../common/UiIcon.vue'
const props = withDefaults(defineProps<{ role?: 'teacher' | 'student' }>(), { role: 'teacher' })
const workspace = useWorkspace(), simulator = useSimulator(), search = ref(''), type = ref(''), publishFilter = ref(''), selectedIds = ref<string[]>([]), input = ref<HTMLInputElement>(), busy = ref(false), removing = ref<string[] | null>(null), draft = ref<WorkspaceFile | null>(null), preview = ref<WorkspaceFile | null>(null), previewText = ref(''), previewUrl = ref(''), previewError = ref('')
const visibleFiles = computed(() => workspace.data.files.filter(file => props.role === 'teacher' || workspace.canReadFile(file)))
function category(file: WorkspaceFile) { return /\.pdf$/i.test(file.name) ? 'PDF' : /^image\//.test(file.type) || /\.(png|jpe?g|gif|webp|svg)$/i.test(file.name) ? '图片' : /^text\//.test(file.type) || /\.(txt|csv|json|md)$/i.test(file.name) ? '文本' : '其他' }
const filtered = computed(() => visibleFiles.value.filter(file => (!type.value || category(file) === type.value) && (!publishFilter.value || (publishFilter.value === 'published' ? !!file.publishedAt : !file.publishedAt)) && matches(file.name, search.value)))
const { page, pageSize, rows } = usePagination(filtered, 10)
watch([search, type, publishFilter], () => { page.value = 1 })
function resetPreview() { if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); previewUrl.value = ''; previewText.value = ''; previewError.value = ''; preview.value = null }
onBeforeUnmount(resetPreview)
async function add(files: File[]) { if (props.role !== 'teacher') return; busy.value = true; try { await workspace.addFiles(files) } finally { busy.value = false } }
async function upload(event: Event) { const target = event.target as HTMLInputElement; await add([...target.files || []]); target.value = '' }
function drop(event: DragEvent) { event.preventDefault(); if (event.dataTransfer?.files.length) void add([...event.dataTransfer.files]) }
async function showPreview(file: WorkspaceFile) {
  resetPreview(); preview.value = file; previewText.value = '正在读取本地文件内容…'
  try {
    const blob = await workspace.getFile(file)
    if (preview.value?.id !== file.id) return
    if (category(file) === '文本') { previewText.value = await blob.slice(0, 160000).text(); if (blob.size > 160000) previewText.value += '\n\n（预览仅显示前 160 KB，完整内容请另存为。）' }
    else if (category(file) === '图片' && !/\.svg$/i.test(file.name)) { previewText.value = ''; previewUrl.value = URL.createObjectURL(blob) }
    else previewText.value = '已找到本地文件内容。浏览器不能打开原文件所在文件夹；此类型请使用“另存为”下载后查看。'
  } catch (error) { previewText.value = ''; previewError.value = error instanceof Error ? error.message : '读取失败。' }
}
function saveMetadata() { if (!draft.value) return; if (!draft.value.name.trim()) { simulator.notify('文件名不能为空。', 'warning'); return }; const index = workspace.data.files.findIndex(file => file.id === draft.value?.id); if (index >= 0) workspace.data.files.splice(index, 1, clone(draft.value)); workspace.persist(); simulator.notify('本地文件设置已保存，不影响用户原文件。', 'success'); draft.value = null }
function publish() { if (draft.value && workspace.publishFile(draft.value)) draft.value = null }
async function remove() { if (removing.value) for (const id of removing.value) await workspace.removeFile(id); selectedIds.value = []; removing.value = null }
async function downloadSelected() { for (const file of filtered.value.filter(file => selectedIds.value.includes(file.id))) await workspace.downloadFile(file) }
</script>
<template>
  <div class="ws-note"><UiIcon name="FolderOpen" :size="16" />{{ role === 'teacher' ? '文件管理：实际用户文件保存在本浏览器 IndexedDB；发布只改变本地资料可见性。移除不会删除磁盘原文件。' : '学生文件列表：读取教师在本浏览器发布或附加到指派任务的文件，不从服务器下载。' }}</div>
  <div class="toolbar"><div class="search-input"><UiIcon name="Search" :size="16" /><input v-model="search" class="field" placeholder="搜索文件名" /></div><select v-model="type" class="field" style="width:125px"><option value="">全部类型</option><option>PDF</option><option>图片</option><option>文本</option><option>其他</option></select><select v-if="role === 'teacher'" v-model="publishFilter" class="field" style="width:125px"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">未发布</option></select><button class="btn" @click="search = ''; type = ''; publishFilter = ''; simulator.notify('已刷新本地文件元数据；打开或下载时会检查实际文件内容。')"><UiIcon name="RefreshCw" :size="15" />{{ role === 'teacher' ? '刷新文件' : '获取文件（本地）' }}</button><span class="spacer" /><button v-if="selectedIds.length" class="btn" @click="downloadSelected">批量另存为 {{ selectedIds.length }} 个</button><button v-if="role === 'teacher'" class="btn btn-primary" :disabled="busy" @click="input?.click()"><UiIcon name="FilePlus2" :size="15" />{{ busy ? '正在写入本地文件库…' : '添加文件' }}</button><input ref="input" type="file" multiple hidden @change="upload" /></div>
  <div v-if="role === 'teacher'" class="ws-upload-zone" @click="input?.click()" @dragover.prevent @drop="drop"><UiIcon name="UploadCloud" :size="25" style="margin-bottom:8px" /><div>拖入文件，或点击选择要分发给学生的文件</div><small class="ws-subtext">每个文件最大 50 MB · 不上传网络 · 写入失败会明确保留为本会话内存文件</small></div>
  <section class="ws-panel" style="margin-top:17px"><header class="ws-panel-header"><h3>{{ role === 'teacher' ? '文件列表' : '学生文件列表' }}</h3><span class="badge">{{ filtered.length }} 个文件</span></header><div class="ws-panel-body"><div class="ws-table-wrap"><table class="data-table"><thead><tr><th style="width:35px"><input type="checkbox" :checked="!!rows.length && rows.every(file => selectedIds.includes(file.id))" aria-label="选择当前页文件" @change="selectedIds = ($event.target as HTMLInputElement).checked ? [...new Set([...selectedIds, ...rows.map(file => file.id)])] : selectedIds.filter(id => !rows.some(file => file.id === id))" /></th><th>文件名</th><th>类型</th><th>大小</th><th>添加时间</th><th>发布状态 / 本地存储</th><th>操作</th></tr></thead><tbody><tr v-for="file in rows" :key="file.id"><td><input v-model="selectedIds" type="checkbox" :value="file.id" :aria-label="'选择' + file.name" /></td><td style="min-width:180px"><div class="ws-inline"><UiIcon :name="category(file) === '图片' ? 'Image' : 'FileText'" :size="18" /><strong style="font-weight:500">{{ file.name }}</strong></div></td><td>{{ file.name.split('.').pop()?.toUpperCase() || category(file) }}</td><td class="ws-nowrap">{{ formatBytes(file.size) }}</td><td class="ws-nowrap">{{ formatDate(file.addedAt) }}</td><td><span class="badge" :class="file.publishedAt ? 'badge-success' : 'badge-muted'">{{ file.publishedAt ? '本地已发布' : '未发布' }}</span><small class="ws-subtext" style="display:block;margin-top:5px">{{ file.storage === 'builtin' ? '内置本地文本' : file.storage === 'indexeddb' ? '浏览器文件库' : '仅本会话内存' }}</small></td><td><div class="ws-inline"><button class="btn btn-sm" @click="showPreview(file)">{{ role === 'teacher' ? '位置 / 预览' : '预览' }}</button><button class="btn btn-sm" @click="workspace.downloadFile(file)"><UiIcon name="Download" :size="13" />另存为</button><button v-if="role === 'teacher'" class="btn btn-sm" @click="draft = clone(file)">设置 / 下发</button><button v-if="role === 'teacher'" class="btn btn-sm btn-danger" @click="removing = [file.id]">移除</button></div></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty-state"><UiIcon name="FolderOpen" :size="46" class="ws-empty-icon" /><p>{{ role === 'teacher' ? '暂无文件，请添加用户文件。' : '没有分配给当前本地身份的文件。' }}</p></td></tr></tbody></table></div><WorkspacePager v-model:page="page" v-model:page-size="pageSize" :total="filtered.length" /><div class="ws-inline" style="margin-top:13px"><span class="ws-subtext">总文件数：{{ visibleFiles.length }} · 选中 {{ selectedIds.length }} 个</span><span class="spacer" /><button v-if="role === 'teacher' && selectedIds.length" class="btn btn-sm btn-danger" @click="removing = [...selectedIds]">移除选中</button><button class="btn btn-sm" @click="simulator.downloadJson('本地文件列表.json', { files: visibleFiles, note: '只有元数据，没有任何远程 URL；文件内容需逐个另存。' })">导出文件列表</button></div></div></section>
  <BaseModal v-if="draft" title="文件设置 / 下发文件（本地）" :width="650" @close="draft = null"><div class="ws-modal-content ws-stack"><label class="field-group"><span>文件名</span><input v-model="draft.name" class="field" maxlength="180" /></label><div class="ws-details"><div class="ws-detail-item"><span>大小</span><strong>{{ formatBytes(draft.size) }}</strong></div><div class="ws-detail-item"><span>添加时间</span><strong>{{ formatDate(draft.addedAt) }}</strong></div></div><label class="checkbox-label"><input v-model="draft.allStudents" type="checkbox" />全体人员可下载</label><div v-if="!draft.allStudents" class="ws-transfer-list" style="height:220px"><label v-for="student in workspace.data.students" :key="student.id" class="checkbox-label"><input v-model="draft.participants" type="checkbox" :value="student.id" />{{ student.name }} · {{ student.studentNo }}</label></div><div class="ws-note">“发布文件”仅使本浏览器学生资料页可见。不会创建伪网络链接，也不能控制其他电脑下载。</div></div><template #footer><button class="btn" @click="draft = null">取消</button><button class="btn" @click="saveMetadata">仅保存设置</button><button class="btn btn-primary" @click="publish">发布文件</button></template></BaseModal>
  <BaseModal v-if="preview" :title="'本地文件位置 / 预览 · ' + preview.name" :width="900" @close="resetPreview"><div class="ws-modal-content ws-stack"><div class="ws-note">本地位置：{{ preview.origin === 'builtin' ? '应用内置文本' : preview.storage === 'indexeddb' ? '当前浏览器 IndexedDB / simulator_web.workspace.files' : '本会话内存' }}。浏览器不能打开用户磁盘文件夹。</div><div v-if="previewError" class="ws-form-error">{{ previewError }}</div><img v-if="previewUrl" :src="previewUrl" :alt="preview.name" style="max-height:430px;object-fit:contain" /><pre v-else-if="previewText" class="ws-json-preview" style="font-family:inherit">{{ previewText }}</pre></div><template #footer><button class="btn" @click="resetPreview">关闭</button><button class="btn btn-primary" @click="workspace.downloadFile(preview)">另存为完整文件</button></template></BaseModal>
  <ConfirmDialog v-if="removing" title="移除本地文件" :message="`确定从管理列表移除 ${removing.length} 个文件？此浏览器保存的内容和任务附件引用会移除，但不会删除用户原始文件。`" danger @confirm="remove" @close="removing = null" />
</template>
